parameters.jsonBody:
={{ JSON.stringify({
  asset_id: $('Prepare Asset Row').first().json.asset_id,
  cover_inputs: $('Parse Variants and Prepare Rows').first().json.cover_inputs,
  app_url: 'https://minions.getminions.ai'
}) }}

={{ JSON.stringify($('Split Claims Rows').all().map(i => i.json).filter(c => c && c.claim_id).map(c => ({
  id: c.claim_id,
  asset_id: c.asset_id,
  claim_text: c.claim_text || '',
  claim_type: c.claim_type || 'ANECDOTE',
  source: c.source_url || null,
  verified: c.verified || 'N',
  confidence_score: c.verified === 'Y' ? 0.95 : 0.5,
  notes: [c.source_title, c.source_date].filter(Boolean).join(' | ') || null
}))) }}

={{ (() => {
  const row = $('Prepare Asset Row').first().json;
  const idea = $('Select Target').first().json || {};
  return JSON.stringify({
    id: row.idea_id,
    client_id: row.client_id || null,
    raw_idea: idea.raw_idea || row.title,
    angle: idea.angle || '',
    audience: row.audience || 'ICP',
    target_trade: row.target_trade || '',
    pillar: idea.pillar || '',
    source: idea.source || 'HARVESTER',
    source_url: idea.source_url || null,
    source_title: idea.source_title || null,
    signals: idea.signals || [],
    status: 'REVIEW',
    priority: idea.priority || 'HIGH',
    why: idea.why || null,
    icp_relevance: Number(idea.icp_relevance) || 4,
    evidence_required: idea.evidence_required || 'N',
    draft_asset_id: row.asset_id,
    updated_at: new Date().toISOString()
  });
})() }}
